// SPDX-License-Identifier: MIT
pragma solidity >=0.7.5;

/**
 * @title IV3FactoryRegistry
 * @notice View surface of the protocol registry the quoters authenticate pools against.
 * @dev Mirrors the metadex `FactoryRegistry` reads the Metarouter uses to validate pools (a pool is a "target" and a
 *      pool factory a "target factory"). This is intentionally distinct from `IFactoryRegistry` under
 *      `contracts/core`, which carries the write surface the CL factory and pool need.
 */
interface IV3FactoryRegistry {
  /**
   * @notice True when a target (pool) factory is in the approval set.
   * @dev Gates pool creation only: the quoters never read it, since unregistering a factory keeps its records.
   * @param targetFactory The pool factory to check.
   * @return Whether the factory is approved.
   */
  function isTargetFactoryApproved(address targetFactory) external view returns (bool);

  /**
   * @notice The target factory that deployed each target (pool). Written once when the factory records the target.
   * @dev Zero for an unknown target, so a nonzero result names the pool's factory without trusting its self-reported
   *      one. The quoters still require that factory to list the pool (`isPool`) before trusting it.
   * @param target The target (pool) to resolve.
   * @return The deploying target factory, or zero for an unknown target.
   */
  function targetToFactory(address target) external view returns (address);
}

contracts/periphery/libraries/LiquidityA.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

import 'contracts/core/libraries/FixedPoint96.sol';
import 'contracts/core/libraries/FullMath.sol';

/// @title Liquidity amount functions
/// @notice Provides functions for computing liquidity amounts from token amounts and prices
library LiquidityAmounts {
  /// @notice Downcasts uint256 to uint128
  /// @param x The uint258 to be downcasted
  /// @return y The passed value, downcasted to uint128
  function toUint128(uint256 x) private pure returns (uint128 y) {
    require((y = uint128(x)) == x);
  }

  /// @notice Computes the amount of liquidity received for a given amount of token0 and price range
  /// @dev Calculates amount0 * (sqrt(upper) * sqrt(lower)) / (sqrt(upper) - sqrt(lower))
  /// @param sqrtRatioAX96 A sqrt price representing the first tick boundary
  /// @param sqrtRatioBX96 A sqrt price representing the second tick boundary
  /// @param amount0 The amount0 being sent in
  /// @return liquidity The amount of returned liquidity
  function getLiquidityForAmount0(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint256 amount0
  ) internal pure returns (uint128 liquidity) {
    if (sqrtRatioAX96 > sqrtRatioBX96) (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);
    uint256 intermediate = FullMath.mulDiv(sqrtRatioAX96, sqrtRatioBX96, FixedPoint96.Q96);
    return toUint128(FullMath.mulDiv(amount0, intermediate, sqrtRatioBX96 - sqrtRatioAX96));
  }

  /// @notice Computes the amount of liquidity received for a given amount of token1 and price range
  /// @dev Calculates amount1 / (sqrt(upper) - sqrt(lower)).
  /// @param sqrtRatioAX96 A sqrt price representing the first tick boundary
  /// @param sqrtRatioBX96 A sqrt price representing the second tick boundary
  /// @param amount1 The amount1 being sent in
  /// @return liquidity The amount of returned liquidity
  function getLiquidityForAmount1(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint256 amount1
  ) internal pure returns (uint128 liquidity) {
    if (sqrtRatioAX96 > sqrtRatioBX96) (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);
    return toUint128(FullMath.mulDiv(amount1, FixedPoint96.Q96, sqrtRatioBX96 - sqrtRatioAX96));
  }

  /// @notice Computes the maximum amount of liquidity received for a given amount of token0, token1, the current
  /// pool prices and the prices at the tick boundaries
  /// @param sqrtRatioX96 A sqrt price representing the current pool prices
  /// @param sqrtRatioAX96 A sqrt price representing the first tick boundary
  /// @param sqrtRatioBX96 A sqrt price representing the second tick boundary
  /// @param amount0 The amount of token0 being sent in
  /// @param amount1 The amount of token1 being sent in
  /// @return liquidity The maximum amount of liquidity received
  function getLiquidityForAmounts(
    uint160 sqrtRatioX96,
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint256 amount0,
    uint256 amount1
  ) internal pure returns (uint128 liquidity) {
    if (sqrtRatioAX96 > sqrtRatioBX96) {
      (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);
    }

    if (sqrtRatioX96 <= sqrtRatioAX96) {
      liquidity = getLiquidityForAmount0(sqrtRatioAX96, sqrtRatioBX96, amount0);
    } else if (sqrtRatioX96 < sqrtRatioBX96) {
      uint128 liquidity0 = getLiquidityForAmount0(sqrtRatioX96, sqrtRatioBX96, amount0);
      uint128 liquidity1 = getLiquidityForAmount1(sqrtRatioAX96, sqrtRatioX96, amount1);

      liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
    } else {
      liquidity = getLiquidityForAmount1(sqrtRatioAX96, sqrtRatioBX96, amount1);
    }
  }

  /// @notice Computes the amount of token0 for a given amount of liquidity and a price range
  /// @param sqrtRatioAX96 A sqrt price representing the first tick boundary
  /// @param sqrtRatioBX96 A sqrt price representing the second tick boundary
  /// @param liquidity The liquidity being valued
  /// @return amount0 The amount of token0
  function getAmount0ForLiquidity(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint128 liquidity
  ) internal pure returns (uint256 amount0) {
    if (sqrtRatioAX96 > sqrtRatioBX96) {
      (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);
    }

    return FullMath.mulDiv(uint256(liquidity) << FixedPoint96.RESOLUTION, sqrtRatioBX96 - sqrtRatioAX96, sqrtRatioBX96)
      / sqrtRatioAX96;
  }

  /// @notice Computes the amount of token1 for a given amount of liquidity and a price range
  /// @param sqrtRatioAX96 A sqrt price representing the first tick boundary
  /// @param sqrtRatioBX96 A sqrt price representing the second tick boundary
  /// @param liquidity The liquidity being valued
  /// @return amount1 The amount of token1
  function getAmount1ForLiquidity(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint128 liquidity
  ) internal pure returns (uint256 amount1) {
    if (sqrtRatioAX96 > sqrtRatioBX96) {
      (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);
    }

    return FullMath.mulDiv(liquidity, sqrtRatioBX96 - sqrtRatioAX96, FixedPoint96.Q96);
  }

  /// @notice Computes the token0 and token1 value for a given amount of liquidity, the current
  /// pool prices and the prices at the tick boundaries
  /// @param sqrtRatioX96 A sqrt price representing the current pool prices
  /// @param sqrtRatioAX96 A sqrt price representing the first tick boundary
  /// @param sqrtRatioBX96 A sqrt price representing the second tick boundary
  /// @param liquidity The liquidity being valued
  /// @return amount0 The amount of token0
  /// @return amount1 The amount of token1
  function getAmountsForLiquidity(
    uint160 sqrtRatioX96,
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint128 liquidity
  ) internal pure returns (uint256 amount0, uint256 amount1) {
    if (sqrtRatioAX96 > sqrtRatioBX96) {
      (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);
    }

    if (sqrtRatioX96 <= sqrtRatioAX96) {
      amount0 = getAmount0ForLiquidity(sqrtRatioAX96, sqrtRatioBX96, liquidity);
    } else if (sqrtRatioX96 < sqrtRatioBX96) {
      amount0 = getAmount0ForLiquidity(sqrtRatioX96, sqrtRatioBX96, liquidity);
      amount1 = getAmount1ForLiquidity(sqrtRatioAX96, sqrtRatioX96, liquidity);
    } else {
      amount1 = getAmount1ForLiquidity(sqrtRatioAX96, sqrtRatioBX96, liquidity);
    }
  }
}

contracts/periphery/libraries/Metaquoter.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;

import {SafeMath} from '@openzeppelin/contracts/math/SafeMath.sol';

import {FullMath} from 'contracts/core/libraries/FullMath.sol';

/**
 * @title MetaquoterLib
 * @notice Holds the stateless helpers Metaquoter quotes with: the stable-pool invariant, the 512-bit product's high
 *         word, and the swap-callback revert decoder.
 * @dev Every function is `internal` and pure, so they inline into the quoter.
 */
library MetaquoterLib {
  using SafeMath for uint256;

  /**
   * @notice Parses the numeric quote from a swap callback revert payload, bubbling any other revert.
   * @param reason The revert payload to parse.
   * @return amount The quoted amount: the output for exact input, the input for exact output.
   * @return sqrtPriceX96After The pool's square-root price after the swap.
   * @return tickAfter The pool's tick after the swap.
   */
  function parseRevertReason(bytes memory reason)
    internal
    pure
    returns (uint256 amount, uint160 sqrtPriceX96After, int24 tickAfter)
  {
    if (reason.length != 0x60) {
      if (reason.length < 0x44) revert('Unexpected error');
      assembly {
        reason := add(reason, 0x04)
      }
      revert(abi.decode(reason, (string)));
    }
    return abi.decode(reason, (uint256, uint160, int24));
  }

  /**
   * @notice Returns the most significant 256 bits of the 512-bit product `a * b`.
   * @dev The low word is never needed: `FullMath.mulDiv(a, b, denominator)` can represent its quotient in a uint256
   *      iff this high word is below `denominator`, which is the only question the quoter asks of the product.
   *      Computed with the same `mulmod` prologue `mulDiv` uses internally; the wrapping `mul` is deliberate.
   * @param a The multiplicand.
   * @param b The multiplier.
   * @return high The high 256 bits of the product.
   */
  function mul512High(uint256 a, uint256 b) internal pure returns (uint256 high) {
    assembly {
      let mm := mulmod(a, b, not(0))
      let prod0 := mul(a, b)
      high := sub(sub(mm, prod0), lt(mm, prod0))
    }
  }

  /**
   * @notice Returns the stable-pool invariant for decimal-normalized token amounts.
   * @param amount0 The decimal-normalized amount of `token0`.
   * @param amount1 The decimal-normalized amount of `token1`.
   * @return k The stable-pool invariant.
   */
  function stableK(uint256 amount0, uint256 amount1) internal pure returns (uint256 k) {
    uint256 product = FullMath.mulDiv(amount0, amount1, 1e18);
    uint256 squares = FullMath.mulDiv(amount0, amount0, 1e18).add(FullMath.mulDiv(amount1, amount1, 1e18));
    k = FullMath.mulDiv(product, squares, 1e18);
  }
}

contracts/periphery/libraries/PoolTicksC.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.6.0;

import 'contracts/core/interfaces/ICLPool.sol';

library PoolTicksCounter {
  /// @dev This function counts the number of initialized ticks that would incur a gas cost between tickBefore and tickAfter.
  /// When tickBefore and/or tickAfter themselves are initialized, the logic over whether we should count them depends on the
  /// direction of the swap. If we are swapping upwards (tickAfter > tickBefore) we don't want to count tickBefore but we do
  /// want to count tickAfter. The opposite is true if we are swapping downwards.
  function countInitializedTicksCrossed(
    ICLPool self,
    int24 tickBefore,
    int24 tickAfter
  ) internal view returns (uint32 initializedTicksCrossed) {
    int16 wordPosLower;
    int16 wordPosHigher;
    uint8 bitPosLower;
    uint8 bitPosHigher;
    bool tickBeforeInitialized;
    bool tickAfterInitialized;

    {
      // Get the key and offset in the tick bitmap of the active tick before and after the swap.
      int16 wordPos = int16((tickBefore / self.tickSpacing()) >> 8);
      uint8 bitPos = uint8((tickBefore / self.tickSpacing()) % 256);

      int16 wordPosAfter = int16((tickAfter / self.tickSpacing()) >> 8);
      uint8 bitPosAfter = uint8((tickAfter / self.tickSpacing()) % 256);

      // In the case where tickAfter is initialized, we only want to count it if we are swapping downwards.
      // If the initializable tick after the swap is initialized, our original tickAfter is a
      // multiple of tick spacing, and we are swapping downwards we know that tickAfter is initialized
      // and we shouldn't count it.
      tickAfterInitialized = ((self.tickBitmap(wordPosAfter) & (1 << bitPosAfter)) > 0)
        && ((tickAfter % self.tickSpacing()) == 0) && (tickBefore > tickAfter);

      // In the case where tickBefore is initialized, we only want to count it if we are swapping upwards.
      // Use the same logic as above to decide whether we should count tickBefore or not.
      tickBeforeInitialized = ((self.tickBitmap(wordPos) & (1 << bitPos)) > 0)
        && ((tickBefore % self.tickSpacing()) == 0) && (tickBefore < tickAfter);

      if (wordPos < wordPosAfter || (wordPos == wordPosAfter && bitPos <= bitPosAfter)) {
        wordPosLower = wordPos;
        bitPosLower = bitPos;
        wordPosHigher = wordPosAfter;
        bitPosHigher = bitPosAfter;
      } else {
        wordPosLower = wordPosAfter;
        bitPosLower = bitPosAfter;
        wordPosHigher = wordPos;
        bitPosHigher = bitPos;
      }
    }

    // Count the number of initialized ticks crossed by iterating through the tick bitmap.
    // Our first mask should include the lower tick and everything to its left.
    uint256 mask = type(uint256).max << bitPosLower;
    while (wordPosLower <= wordPosHigher) {
      // If we're on the final tick bitmap page, ensure we only count up to our
      // ending tick.
      if (wordPosLower == wordPosHigher) {
        mask = mask & (type(uint256).max >> (255 - bitPosHigher));
      }

      uint256 masked = self.tickBitmap(wordPosLower) & mask;
      initializedTicksCrossed += countOneBits(masked);
      wordPosLower++;
      // Reset our mask so we consider all bits on the next iteration.
      mask = type(uint256).max;
    }

    if (tickAfterInitialized) {
      initializedTicksCrossed -= 1;
    }

    if (tickBeforeInitialized) {
      initializedTicksCrossed -= 1;
    }

    return initializedTicksCrossed;
  }

  function countOneBits(uint256 x) private pure returns (uint16) {
    uint16 bits = 0;
    while (x != 0) {
      bits++;
      x &= (x - 1);
    }
    return bits;
  }
}

contracts/core/interfaces/IFactoryRegist.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6;

/**
 * @title IFactoryRegistry
 * @notice Surface of the metadex `FactoryRegistry` the CL stack calls.
 * @dev A pool is a "target" and a pool factory a "target factory". The periphery keeps its own read-only mirror in
 *      `contracts/periphery/interfaces/IV3FactoryRegistry.sol` for the quoters.
 */
interface IFactoryRegistry {
  /**
   * @notice Registers a gauge factory and the target factory it serves as a pair, writing their permanent link.
   * @param gaugeFactory The gauge factory to register.
   * @param targetFactory The target (pool) factory the gauge factory serves.
   */
  function registerFactories(address gaugeFactory, address targetFactory) external;

  /**
   * @notice Records a freshly deployed target. Called by the target factory inside its own creation function.
   * @param target The deployed target (pool).
   */
  function registerTarget(address target) external;

  /**
   * @notice True when a target (pool) factory is in the approval set.
   * @param targetFactory The target factory to check.
   * @return Whether the factory is approved.
   */
  function isTargetFactoryApproved(address targetFactory) external view returns (bool);

  /**
   * @notice The gauge factory serving a target factory.
   * @param targetFactory The target factory to resolve.
   * @return The linked gauge factory, zero for an unlinked factory.
   */
  function targetFactoryToGaugeFactory(address targetFactory) external view returns (address);

  /**
   * @notice The gauge over a target (pool).
   * @param target The target to resolve.
   * @return The gauge for `target`, zero when none is recorded.
   */
  function targetToGauge(address target) external view returns (address);

  /**
   * @notice Effective emission cap for a gauge, resolved through the factory that deployed it.
   * @dev Returns zero when the gauge is unknown or the factory call reverts.
   * @param gauge The gauge to resolve.
   * @return The effective cap in tokens per second.
   */
  function emissionCap(address gauge) external view returns (uint128);
}

contracts/core/interfaces/pool/ICLPoolAc.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Permissionless pool actions
/// @notice Contains pool methods that can be called by anyone
interface ICLPoolActions {
  /// @notice Initialize function used in proxy deployment
  /// @dev Can be called once only
  /// Price is represented as a sqrt(amountToken1/amountToken0) Q64.96 value
  /// @dev not locked because it initializes unlocked
  /// @param _factory The CL factory contract address
  /// @param _token0 The first token of the pool by address sort order
  /// @param _token1 The second token of the pool by address sort order
  /// @param _tickSpacing The pool tick spacing
  /// @param _factoryRegistry The address of the factory registry managing the pool factory
  /// @param _sqrtPriceX96 The initial sqrt price of the pool, as a Q64.96
  function initialize(
    address _factory,
    address _token0,
    address _token1,
    int24 _tickSpacing,
    address _factoryRegistry,
    uint160 _sqrtPriceX96
  ) external;

  /// @notice Initialize gauge and nft manager
  /// @dev Callable only once, by the gauge factory
  /// @param _gauge The gauge corresponding to this pool
  /// @param _nft The position manager used for position management
  function setGaugeAndPositionManager(address _gauge, address _nft) external;

  /// @notice Adds liquidity for the given recipient/tickLower/tickUpper position
  /// @dev The caller of this method receives a callback in the form of ICLMintCallback#uniswapV3MintCallback
  /// in which they must pay any token0 or token1 owed for the liquidity. The amount of token0/token1 due depends
  /// on tickLower, tickUpper, the amount of liquidity, and the current price.
  /// @param recipient The address for which the liquidity will be created
  /// @param tickLower The lower tick of the position in which to add liquidity
  /// @param tickUpper The upper tick of the position in which to add liquidity
  /// @param amount The amount of liquidity to mint
  /// @param data Any data that should be passed through to the callback
  /// @return amount0 The amount of token0 that was paid to mint the given amount of liquidity. Matches the value in the callback
  /// @return amount1 The amount of token1 that was paid to mint the given amount of liquidity. Matches the value in the callback
  function mint(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    bytes calldata data
  ) external returns (uint256 amount0, uint256 amount1);

  /// @notice Collects tokens owed to a position
  /// @dev Does not recompute fees earned, which must be done either via mint or burn of any amount of liquidity.
  /// Collect must be called by the position owner. To withdraw only token0 or only token1, amount0Requested or
  /// amount1Requested may be set to zero. To withdraw all tokens owed, caller may pass any value greater than the
  /// actual tokens owed, e.g. type(uint128).max. Tokens owed may be from accumulated swap fees or burned liquidity.
  /// @param recipient The address which should receive the fees collected
  /// @param tickLower The lower tick of the position for which to collect fees
  /// @param tickUpper The upper tick of the position for which to collect fees
  /// @param amount0Requested How much token0 should be withdrawn from the fees owed
  /// @param amount1Requested How much token1 should be withdrawn from the fees owed
  /// @return amount0 The amount of fees collected in token0
  /// @return amount1 The amount of fees collected in token1
  function collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested
  ) external returns (uint128 amount0, uint128 amount1);

  /// @notice Collects tokens owed to a position
  /// @dev Does not recompute fees earned, which must be done either via mint or burn of any amount of liquidity.
  /// Collect must be called by the position owner. To withdraw only token0 or only token1, amount0Requested or
  /// amount1Requested may be set to zero. To withdraw all tokens owed, caller may pass any value greater than the
  /// actual tokens owed, e.g. type(uint128).max. Tokens owed may be from accumulated swap fees or burned liquidity.
  /// @param recipient The address which should receive the fees collected
  /// @param tickLower The lower tick of the position for which to collect fees
  /// @param tickUpper The upper tick of the position for which to collect fees
  /// @param amount0Requested How much token0 should be withdrawn from the fees owed
  /// @param amount1Requested How much token1 should be withdrawn from the fees owed
  /// @param owner Owner of the position in the pool (nft manager or gauge)
  /// @return amount0 The amount of fees collected in token0
  /// @return amount1 The amount of fees collected in token1
  function collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested,
    address owner
  ) external returns (uint128 amount0, uint128 amount1);

  /// @notice Burn liquidity from the sender and account tokens owed for the liquidity to the position
  /// @dev Can be used to trigger a recalculation of fees owed to a position by calling with an amount of 0
  /// @dev Fees must be collected separately via a call to #collect
  /// @param tickLower The lower tick of the position for which to burn liquidity
  /// @param tickUpper The upper tick of the position for which to burn liquidity
  /// @param amount How much liquidity to burn
  /// @return amount0 The amount of token0 sent to the recipient
  /// @return amount1 The amount of token1 sent to the recipient
  function burn(int24 tickLower, int24 tickUpper, uint128 amount) external returns (uint256 amount0, uint256 amount1);

  /// @notice Burn liquidity from the supplied owner and account tokens owed for the liquidity to the position
  /// @dev Can be used to trigger a recalculation of fees owed to a position by calling with an amount of 0
  /// @dev Fees must be collected separately via a call to #collect
  /// @param tickLower The lower tick of the position for which to burn liquidity
  /// @param tickUpper The upper tick of the position for which to burn liquidity
  /// @param amount How much liquidity to burn
  /// @param owner Owner of the position in the pool (nft manager or gauge)
  /// @return amount0 The amount of token0 sent to the recipient
  /// @return amount1 The amount of token1 sent to the recipient
  function burn(
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    address owner
  ) external returns (uint256 amount0, uint256 amount1);

  /// @notice Convert existing liquidity into staked liquidity
  /// @notice Only callable by the gauge associated with this pool
  /// @param stakedLiquidityDelta The amount by which to increase or decrease the staked liquidity
  /// @param tickLower The lower tick of the position for which to stake liquidity
  /// @param tickUpper The upper tick of the position for which to stake liquidity
  function stake(int128 stakedLiquidityDelta, int24 tickLower, int24 tickUpper) external;

  /// @notice Swap token0 for token1, or token1 for token0
  /// @dev The caller of this method receives a callback in the form of ICLSwapCallback#uniswapV3SwapCallback
  /// @param recipient The address to receive the output of the swap
  /// @param zeroForOne The direction of the swap, true for token0 to token1, false for token1 to token0
  /// @param amountSpecified The amount of the swap, which implicitly configures the swap as exact input (positive), or exact output (negative)
  /// @param sqrtPriceLimitX96 The Q64.96 sqrt price limit. If zero for one, the price cannot be less than this
  /// value after the swap. If one for zero, the price cannot be greater than this value after the swap
  /// @param data Any data to be passed through to the callback
  /// @return amount0 The delta of the balance of token0 of the pool, exact when negative, minimum when positive
  /// @return amount1 The delta of the balance of token1 of the pool, exact when negative, minimum when positive
  function swap(
    address recipient,
    bool zeroForOne,
    int256 amountSpecified,
    uint160 sqrtPriceLimitX96,
    bytes calldata data
  ) external returns (int256 amount0, int256 amount1);

  /// @notice Receive token0 and/or token1 and pay it back, plus a fee, in the callback
  /// @dev The caller of this method receives a callback in the form of ICLFlashCallback#uniswapV3FlashCallback
  /// @dev Can be used to donate underlying tokens pro-rata to currently in-range liquidity providers by calling
  /// with 0 amount{0,1} and sending the donation amount(s) from the callback
  /// @param recipient The address which will receive the token0 and token1 amounts
  /// @param amount0 The amount of token0 to send
  /// @param amount1 The amount of token1 to send
  /// @param data Any data to be passed through to the callback
  function flash(address recipient, uint256 amount0, uint256 amount1, bytes calldata data) external;

  /// @notice Increase the maximum number of price and liquidity observations that this pool will store
  /// @dev This method is no-op if the pool already has an observationCardinalityNext greater than or equal to
  /// the input observationCardinalityNext.
  /// @param observationCardinalityNext The desired minimum number of observations for the pool to store
  function increaseObservationCardinalityNext(uint16 observationCardinalityNext) external;

  /// @notice Settles the pool's reward growth to the current block timestamp and returns the accrued rollover
  /// @dev Only callable by the gauge. Pulls the emissions accrued since the last settlement through the gauge.
  /// @return _rollover the emissions accumulated while no staked liquidity was in range. Reset to 0 after this call.
  function settleToBlock() external returns (uint256 _rollover);
}

contracts/core/interfaces/pool/ICLPoolCo.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Pool state that never changes
/// @notice These parameters are not defined as immutable (due to proxy pattern) but are effectively immutable.
/// @notice i.e., the methods will always return the same values
interface ICLPoolConstants {
  /// @notice The contract that deployed the pool, which must adhere to the ICLFactory interface
  /// @return The contract address
  function factory() external view returns (address);

  /// @notice The first of the two tokens of the pool, sorted by address
  /// @return The token contract address
  function token0() external view returns (address);

  /// @notice The second of the two tokens of the pool, sorted by address
  /// @return The token contract address
  function token1() external view returns (address);

  /// @notice The gauge corresponding to this pool
  /// @return The gauge contract address
  function gauge() external view returns (address);

  /// @notice The nft manager
  /// @return The nft manager contract address
  function nft() external view returns (address);

  /// @notice The factory registry that manages pool <> gauge <> reward factory relationships
  /// @return The factory registry contract address
  function factoryRegistry() external view returns (address);

  /// @notice The pool tick spacing
  /// @dev Ticks can only be used at multiples of this value, minimum of 1 and always positive
  /// e.g.: a tickSpacing of 3 means ticks can be initialized every 3rd tick, i.e., ..., -6, -3, 0, 3, 6, ...
  /// This value is an int24 to avoid casting even though it is always positive.
  /// @return The tick spacing
  function tickSpacing() external view returns (int24);

  /// @notice The maximum amount of position liquidity that can use any tick in the range
  /// @dev This parameter is enforced per tick to prevent liquidity from overflowing a uint128 at any point, and
  /// also prevents out-of-range liquidity from being used to prevent adding in-range liquidity to a pool
  /// @return The max amount of liquidity per tick
  function maxLiquidityPerTick() external view returns (uint128);

  /// @notice The ceiling applied to the before/after swap fee.
  /// @return The swap fee ceiling value in pips.
  function SWAP_FEE_CEIL() external view returns (uint256);

  /// @notice The denominator used for fees computation.
  /// @return The denominator value in pips.
  function DENOMINATOR() external view returns (uint256);

  /// @notice The pool type identifier
  /// @return The pool type label to be able to identify the type of pool
  function POOL_TYPE() external view returns (bytes32);
}

contracts/core/interfaces/pool/ICLPoolDe.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Pool state that is not stored
/// @notice Contains view functions to provide information about the pool that is computed rather than stored on the
/// blockchain. The functions here may have variable gas costs.
interface ICLPoolDerivedState {
  /// @notice Returns the cumulative tick and liquidity as of each timestamp `secondsAgo` from the current block timestamp
  /// @dev To get a time weighted average tick or liquidity-in-range, you must call this with two values, one representing
  /// the beginning of the period and another for the end of the period. E.g., to get the last hour time-weighted average tick,
  /// you must call it with secondsAgos = [3600, 0].
  /// @dev The time weighted average tick represents the geometric time weighted average price of the pool, in
  /// log base sqrt(1.0001) of token1 / token0. The TickMath library can be used to go from a tick value to a ratio.
  /// @param secondsAgos From how long ago each cumulative tick and liquidity value should be returned
  /// @return tickCumulatives Cumulative tick values as of each `secondsAgos` from the current block timestamp
  /// @return secondsPerLiquidityCumulativeX128s Cumulative seconds per liquidity-in-range value as of each `secondsAgos` from the current block
  /// timestamp
  function observe(uint32[] calldata secondsAgos)
    external
    view
    returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s);

  /// @notice Returns a snapshot of the tick cumulative, seconds per liquidity and seconds inside a tick range
  /// @dev Snapshots must only be compared to other snapshots, taken over a period for which a position existed.
  /// I.e., snapshots cannot be compared if a position is not held for the entire period between when the first
  /// snapshot is taken and the second snapshot is taken.
  /// @param tickLower The lower tick of the range
  /// @param tickUpper The upper tick of the range
  /// @return tickCumulativeInside The snapshot of the tick accumulator for the range
  /// @return secondsPerLiquidityInsideX128 The snapshot of seconds per liquidity for the range
  /// @return secondsInside The snapshot of seconds per liquidity for the range
  function snapshotCumulativesInside(
    int24 tickLower,
    int24 tickUpper
  ) external view returns (int56 tickCumulativeInside, uint160 secondsPerLiquidityInsideX128, uint32 secondsInside);

  /// @notice The seconds per staked liquidity cumulative projected to the current block timestamp
  /// @return The Q128.128 seconds per staked liquidity cumulative as of the current block
  function getSecondsPerStakedLiquidityCumulativeX128() external view returns (uint160);
}

contracts/core/interfaces/pool/ICLPoolEv.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Events emitted by a pool
/// @notice Contains all events emitted by the pool
interface ICLPoolEvents {
  /// @notice Emitted exactly once by a pool when #initialize is first called on the pool
  /// @dev Mint/Burn/Swap cannot be emitted by the pool before Initialize
  /// @param sqrtPriceX96 The initial sqrt price of the pool, as a Q64.96
  /// @param tick The initial tick of the pool, i.e. log base 1.0001 of the starting price of the pool
  event Initialize(uint160 sqrtPriceX96, int24 tick);

  /// @notice Emitted when liquidity is minted for a given position
  /// @param sender The address that minted the liquidity
  /// @param owner The owner of the position and recipient of any minted liquidity
  /// @param tickLower The lower tick of the position
  /// @param tickUpper The upper tick of the position
  /// @param amount The amount of liquidity minted to the position range
  /// @param amount0 How much token0 was required for the minted liquidity
  /// @param amount1 How much token1 was required for the minted liquidity
  event Mint(
    address sender,
    address indexed owner,
    int24 indexed tickLower,
    int24 indexed tickUpper,
    uint128 amount,
    uint256 amount0,
    uint256 amount1
  );

  /// @notice Emitted when fees are collected by the owner of a position
  /// @dev Collect events may be emitted with zero amount0 and amount1 when the caller chooses not to collect fees
  /// @param owner The owner of the position for which fees are collected
  /// @param tickLower The lower tick of the position
  /// @param tickUpper The upper tick of the position
  /// @param amount0 The amount of token0 fees collected
  /// @param amount1 The amount of token1 fees collected
  event Collect(
    address indexed owner,
    address recipient,
    int24 indexed tickLower,
    int24 indexed tickUpper,
    uint128 amount0,
    uint128 amount1
  );

  /// @notice Emitted when a position's liquidity is removed
  /// @dev Does not withdraw any fees earned by the liquidity position, which must be withdrawn via #collect
  /// @param owner The owner of the position for which liquidity is removed
  /// @param tickLower The lower tick of the position
  /// @param tickUpper The upper tick of the position
  /// @param amount The amount of liquidity to remove
  /// @param amount0 The amount of token0 withdrawn
  /// @param amount1 The amount of token1 withdrawn
  event Burn(
    address indexed owner,
    int24 indexed tickLower,
    int24 indexed tickUpper,
    uint128 amount,
    uint256 amount0,
    uint256 amount1
  );

  /// @notice Emitted by the pool for any swaps between token0 and token1
  /// @param sender The address that initiated the swap call, and that received the callback
  /// @param recipient The address that received the output of the swap
  /// @param amount0 The delta of the token0 balance of the pool
  /// @param amount1 The delta of the token1 balance of the pool
  /// @param sqrtPriceX96 The sqrt(price) of the pool after the swap, as a Q64.96
  /// @param liquidity The liquidity of the pool after the swap
  /// @param tick The log base 1.0001 of price of the pool after the swap
  event Swap(
    address indexed sender,
    address indexed recipient,
    int256 amount0,
    int256 amount1,
    uint160 sqrtPriceX96,
    uint128 liquidity,
    int24 tick
  );

  /// @notice Emitted by the pool for any flashes of token0/token1
  /// @param sender The address that initiated the swap call, and that received the callback
  /// @param recipient The address that received the tokens from flash
  /// @param amount0 The amount of token0 that was flashed
  /// @param amount1 The amount of token1 that was flashed
  /// @param paid0 The amount of token0 paid for the flash, which can exceed the amount0 plus the fee
  /// @param paid1 The amount of token1 paid for the flash, which can exceed the amount1 plus the fee
  event Flash(
    address indexed sender, address indexed recipient, uint256 amount0, uint256 amount1, uint256 paid0, uint256 paid1
  );

  /// @notice Emitted by the pool for increases to the number of observations that can be stored
  /// @dev observationCardinalityNext is not the observation cardinality until an observation is written at the index
  /// just before a mint/swap/burn.
  /// @param observationCardinalityNextOld The previous value of the next observation cardinality
  /// @param observationCardinalityNextNew The updated value of the next observation cardinality
  event IncreaseObservationCardinalityNext(uint16 observationCardinalityNextOld, uint16 observationCardinalityNextNew);

  /// @notice Emitted when the protocol fee is changed by the pool
  /// @param feeProtocol0Old The previous value of the token0 protocol fee
  /// @param feeProtocol1Old The previous value of the token1 protocol fee
  /// @param feeProtocol0New The updated value of the token0 protocol fee
  /// @param feeProtocol1New The updated value of the token1 protocol fee
  event SetFeeProtocol(uint8 feeProtocol0Old, uint8 feeProtocol1Old, uint8 feeProtocol0New, uint8 feeProtocol1New);

  /// @notice Emitted when the collected protocol fees are withdrawn by the gauge
  /// @param recipient The address that receives the collected protocol fees
  /// @param amount0 The amount of token0 protocol fees that is withdrawn
  /// @param amount0 The amount of token1 protocol fees that is withdrawn
  event CollectFees(address indexed recipient, uint128 amount0, uint128 amount1);
}

